"use client";
import { forwardRef, useCallback, useEffect, useRef } from "react";
import "./glass-button.css";
import { useGlassLens } from "./glass-lens.js";

/* Springs, not durations: a press can be reversed mid-flight and the
   button picks up from wherever it is. */
const SPRINGS = {
  smooth: { stiffness: 380, damping: 36 }, // settles with no bounce
  bubble: { stiffness: 420, damping: 19 }, // one soft overshoot
};

const REST = { scale: 1, squish: 0, hx: 0.5, hy: 0, glow: 0 };

const reducedMotion = () =>
  typeof window !== "undefined" &&
  !!window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

const write = (el, values) => {
  for (const key in values) el.style.setProperty(`--g-${key}`, values[key].toFixed(4));
};

/* Drives a handful of CSS variables with one spring loop per button.
   No React re-renders happen while it animates. */
function useSpringVars(ref, springName, still) {
  const state = useRef(null);
  if (!state.current) {
    state.current = { cur: { ...REST }, vel: {}, target: { ...REST }, raf: 0, last: 0 };
  }
  const opts = useRef({});
  opts.current = { springName, still };

  const step = useCallback(
    (now) => {
      const s = state.current;
      const el = ref.current;
      if (!el) {
        s.raf = 0;
        return;
      }
      const spring = SPRINGS[opts.current.springName] || SPRINGS.smooth;
      const dt = Math.min((now - s.last) / 1000, 1 / 30);
      s.last = now;
      let moving = false;
      for (const key in s.cur) {
        const v = s.vel[key] || 0;
        const d = s.target[key] - s.cur[key];
        const nv = v + (spring.stiffness * d - spring.damping * v) * dt;
        s.vel[key] = nv;
        s.cur[key] += nv * dt;
        if (Math.abs(d) < 0.0005 && Math.abs(nv) < 0.005) {
          s.cur[key] = s.target[key];
          s.vel[key] = 0;
        } else {
          moving = true;
        }
      }
      write(el, s.cur);
      s.raf = moving ? requestAnimationFrame(step) : 0;
    },
    [ref]
  );

  const set = useCallback(
    (next) => {
      const s = state.current;
      const el = ref.current;
      Object.assign(s.target, next);
      if (!el) return;
      if (opts.current.still || reducedMotion()) {
        // Keep the light feedback, drop the movement.
        Object.assign(s.cur, s.target, { scale: 1, squish: 0 });
        write(el, s.cur);
        return;
      }
      if (!s.raf) {
        s.last = performance.now();
        s.raf = requestAnimationFrame(step);
      }
    },
    [ref, step]
  );

  useEffect(() => () => cancelAnimationFrame(state.current.raf), []);
  return set;
}

const chain = (own, user) => (event) => {
  if (user) user(event);
  if (!event.defaultPrevented) own(event);
};

/**
 * GlassButton
 *
 * variant   "primary" | "secondary" | "ghost"
 * effect    "flat" | "glass" | "bubble"
 * size      "sm" | "md" | "lg"
 * iconOnly  square button for a single icon (give it an aria-label)
 * motion    "smooth" | "none"
 * loading   shows a spinner and blocks clicks, keeps focus
 */
export const GlassButton = forwardRef(function GlassButton(
  {
    variant = "primary",
    effect = "flat",
    size = "md",
    iconOnly = false,
    motion = "smooth",
    loading = false,
    disabled = false,
    iconLeft,
    iconRight,
    className = "",
    children,
    onClick,
    onPointerEnter,
    onPointerMove,
    onPointerLeave,
    onPointerDown,
    onPointerUp,
    onPointerCancel,
    onKeyDown,
    onKeyUp,
    onBlur,
    ...rest
  },
  forwardedRef
) {
  useGlassLens(effect !== "flat");
  const ref = useRef(null);
  const bubble = effect === "bubble";
  const set = useSpringVars(ref, bubble ? "bubble" : "smooth", motion === "none");
  const inert = disabled || loading;

  const setRef = useCallback(
    (node) => {
      ref.current = node;
      if (typeof forwardedRef === "function") forwardedRef(node);
      else if (forwardedRef) forwardedRef.current = node;
    },
    [forwardedRef]
  );

  useEffect(() => {
    if (inert) set(REST);
  }, [inert, set]);

  const enter = () => {
    if (!inert) set({ glow: 1 });
  };
  const move = (e) => {
    if (inert || e.pointerType !== "mouse") return;
    const r = e.currentTarget.getBoundingClientRect();
    set({
      hx: Math.min(1, Math.max(0, (e.clientX - r.left) / r.width)),
      hy: Math.min(1, Math.max(0, (e.clientY - r.top) / r.height)),
    });
  };
  const leave = () => set(REST);
  // Flat and glass sink slightly. Bubble also squashes, then springs back.
  const press = () => {
    if (!inert) set(bubble ? { scale: 0.96, squish: 0.02, glow: 1 } : { scale: 0.98, glow: 1 });
  };
  const release = () => {
    if (!inert) set({ scale: 1, squish: 0 });
  };
  const keyDown = (e) => {
    if ((e.key === " " || e.key === "Enter") && !e.repeat) press();
  };
  const keyUp = (e) => {
    if (e.key === " " || e.key === "Enter") set({ scale: 1, squish: 0, glow: 0 });
  };

  return (
    <button
      type="button"
      {...rest}
      ref={setRef}
      className={`gb ${className}`.trim()}
      data-variant={variant}
      data-effect={effect}
      data-size={size}
      data-icon-only={iconOnly ? "" : undefined}
      disabled={disabled}
      aria-busy={loading || undefined}
      aria-disabled={loading || undefined}
      onClick={loading ? (e) => e.preventDefault() : onClick}
      onPointerEnter={chain(enter, onPointerEnter)}
      onPointerMove={chain(move, onPointerMove)}
      onPointerLeave={chain(leave, onPointerLeave)}
      onPointerDown={chain(press, onPointerDown)}
      onPointerUp={chain(release, onPointerUp)}
      onPointerCancel={chain(leave, onPointerCancel)}
      onKeyDown={chain(keyDown, onKeyDown)}
      onKeyUp={chain(keyUp, onKeyUp)}
      onBlur={chain(leave, onBlur)}
    >
      {loading ? (
        <span className="gb-spinner" aria-hidden="true" />
      ) : (
        iconLeft && (
          <span className="gb-icon" aria-hidden="true">
            {iconLeft}
          </span>
        )
      )}
      {children != null && <span className="gb-label">{children}</span>}
      {iconRight && (
        <span className="gb-icon" aria-hidden="true">
          {iconRight}
        </span>
      )}
    </button>
  );
});

export default GlassButton;

/* Tokens. Light theme.
   --glass-tint   brand colour of every primary button
   --glass-radius 12px by default; 999px gives a capsule */
:root {
  --glass-tint: #2d6cf6;
  --glass-fg: #14161b;
  --glass-on-tint: #ffffff;
  --glass-radius: 12px;
  --glass-blur: 14px;
  --glass-shadow: 16 20 30; /* rgb channels of the shadow colour */
}

.gb {
  /* Written by the spring loop in GlassButton.jsx */
  --g-scale: 1;
  --g-squish: 0;
  --g-hx: 0.5;
  --g-hy: 0;
  --g-glow: 0;

  --gb-h: 40px;
  --gb-px: 16px;
  --gb-fs: 14px;
  --gb-fg: var(--glass-fg);
  --gb-fill: #fff;
  --gb-backdrop: none;
  --gb-inset: inset 0 0 0 0 transparent;
  --gb-ring: rgb(var(--glass-shadow) / 0.1);
  --gb-drop: rgb(var(--glass-shadow) / 0.12);
  --gb-lift: 4px;
  --gb-rim-hi: transparent;
  --gb-rim-lo: transparent;
  --gb-light: 0.2;

  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5em;
  height: var(--gb-h);
  padding: 0 var(--gb-px);
  border: 0;
  border-radius: min(var(--glass-radius), calc(var(--gb-h) / 2));
  font: inherit;
  font-size: var(--gb-fs);
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1;
  white-space: nowrap;
  color: var(--gb-fg);
  background: var(--gb-fill);
  -webkit-backdrop-filter: var(--gb-backdrop);
  backdrop-filter: var(--gb-backdrop);
  box-shadow:
    var(--gb-inset),
    0 0 0 1px var(--gb-ring),
    0 1px 2px rgb(var(--glass-shadow) / 0.06),
    0 calc(var(--gb-lift) + 3px * var(--g-glow)) calc(var(--gb-lift) * 2.2 + 6px * var(--g-glow))
      calc(var(--gb-lift) * -0.8) var(--gb-drop);
  transform: scale(calc(var(--g-scale) + var(--g-squish)), calc(var(--g-scale) - var(--g-squish)));
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

/* Light that follows the cursor. Invisible at rest. */
.gb::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(
    90% 160% at calc(var(--g-hx) * 100%) calc(var(--g-hy) * 100%),
    rgb(255 255 255 / 0.8),
    transparent 60%
  );
  opacity: calc(var(--gb-light) * var(--g-glow));
}

/* The rim: a thin inner edge, brighter at two opposite corners. */
.gb::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  padding: 0.5px;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(135deg, var(--gb-rim-hi), var(--gb-rim-lo) 38%, var(--gb-rim-lo) 62%, var(--gb-rim-hi));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
}

.gb:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--glass-focus, var(--glass-tint)) 50%, transparent);
  outline-offset: 2px;
}
/* While its menu is open, the open menu already shows where you are */
.gb[aria-expanded="true"]:focus-visible { outline-color: transparent; }

/* Sizes */
.gb[data-size="sm"] { --gb-h: 32px; --gb-px: 12px; --gb-fs: 13px; }
.gb[data-size="lg"] { --gb-h: 48px; --gb-px: 22px; --gb-fs: 15px; }
.gb[data-icon-only] { width: var(--gb-h); padding: 0; }

/* ---------- Primary: the brand colour ---------- */
.gb[data-variant="primary"] {
  --gb-fg: var(--glass-on-tint);
  --gb-fill: linear-gradient(180deg, rgb(255 255 255 / 0.14), transparent 60%), var(--glass-tint);
  --gb-ring: color-mix(in srgb, var(--glass-tint) 80%, #000);
  --gb-drop: color-mix(in srgb, var(--glass-tint) 50%, transparent);
  --gb-rim-hi: rgb(255 255 255 / 0.5);
  --gb-rim-lo: rgb(255 255 255 / 0.2);
}
/* Double edge: dark line outside, light line just inside it */
.gb[data-variant="primary"]::after {
  inset: 1px;
  padding: 0.5px;
  border-radius: calc(min(var(--glass-radius), var(--gb-h) / 2) - 1px);
}

/* ---------- Finish: glass ---------- */
.gb[data-effect="glass"],
.gb[data-effect="bubble"] {
  --gb-backdrop: blur(var(--glass-blur)) saturate(1.8) brightness(1.06);
  --gb-lift: 7px;
  --gb-light: 0.45;
}
.gb[data-effect="glass"][data-variant="secondary"] {
  --gb-fill: linear-gradient(180deg, rgb(255 255 255 / 0.55), rgb(255 255 255 / 0.22));
  --gb-inset: inset 0 1px 0 0 rgb(255 255 255 / 0.9);
  --gb-ring: rgb(var(--glass-shadow) / 0.07);
  --gb-drop: rgb(var(--glass-shadow) / 0.18);
  --gb-rim-hi: rgb(255 255 255 / 1);
  --gb-rim-lo: rgb(255 255 255 / 0.3);
}
.gb[data-effect="glass"][data-variant="primary"] {
  --gb-fill:
    linear-gradient(180deg, rgb(255 255 255 / 0.2), transparent 55%),
    color-mix(in srgb, var(--glass-tint) 76%, transparent);
  --gb-rim-hi: rgb(255 255 255 / 0.65);
  --gb-light: 0.28;
}

/* ---------- Finish: bubble (glass plus a gloss and a rounder belly) ---------- */
.gb[data-effect="bubble"] { --gb-lift: 9px; }
.gb[data-effect="bubble"][data-variant="secondary"] {
  --gb-fill: linear-gradient(180deg, rgb(255 255 255 / 0.85), rgb(255 255 255 / 0.18) 52%, rgb(255 255 255 / 0.34));
  --gb-inset: inset 0 1px 0 0 #fff, inset 0 -8px 12px -7px rgb(var(--glass-shadow) / 0.18);
  --gb-ring: rgb(var(--glass-shadow) / 0.07);
  --gb-drop: rgb(var(--glass-shadow) / 0.2);
  --gb-rim-hi: rgb(255 255 255 / 1);
  --gb-rim-lo: rgb(255 255 255 / 0.3);
}
.gb[data-effect="bubble"][data-variant="primary"] {
  --gb-fill:
    linear-gradient(180deg, rgb(255 255 255 / 0.5), rgb(255 255 255 / 0.06) 48%, transparent),
    color-mix(in srgb, var(--glass-tint) 84%, transparent);
  --gb-inset: inset 0 -8px 12px -6px color-mix(in srgb, var(--glass-tint) 55%, #000);
  --gb-rim-hi: rgb(255 255 255 / 0.7);
  --gb-light: 0.3;
}

/* ---------- Frost: the Mist theme's default look ----------
   Turn on with data-glass-tint="frost" on <html> or any wrapper. The main
   button becomes frosted glass with a bright top and bottom edge, and the
   small controls take a quiet slate. */
[data-glass-tint="frost"] {
  --glass-tint: #5d6675;
  --glass-on-tint: #ffffff;
  --glass-radius: 999px;
}
[data-glass-tint="frost"] .gb[data-variant="primary"] {
  --gb-fg: #353d4d;
  --gb-fill: linear-gradient(180deg, #f4f6fa, #dde2ea 48%, #e8ecf2);
  --gb-backdrop: none;
  --gb-inset: inset 0 1.5px 0 0 rgb(255 255 255 / 0.98), inset 0 -1.5px 0 0 rgb(255 255 255 / 0.8), inset 0 0 14px 0 rgb(255 255 255 / 0.4);
  --gb-ring: rgb(70 82 104 / 0.24);
  --gb-drop: rgb(60 72 98 / 0.4);
  --gb-lift: 10px;
  --gb-rim-hi: rgb(255 255 255 / 0.9);
  --gb-rim-lo: rgb(255 255 255 / 0.1);
  --gb-light: 0.55;
}
/* Frost as glass: the same button, see-through */
[data-glass-tint="frost"] .gb[data-variant="primary"][data-effect="glass"],
[data-glass-tint="frost"] .gb[data-variant="primary"][data-effect="bubble"] {
  --gb-fill: linear-gradient(180deg, rgb(244 246 250 / 0.5), rgb(214 220 231 / 0.2) 48%, rgb(230 235 243 / 0.42));
  --gb-backdrop: blur(14px) saturate(1.7) brightness(1.08);
}
/* Mist: where the browser can (Chromium), the glass also bends what
   is behind it along its rim. glass-lens.js turns this on. */
:root[data-glass-lens] [data-glass-tint="frost"] .gb:not([data-variant="ghost"])[data-effect="glass"],
:root[data-glass-lens] [data-glass-tint="frost"] .gb:not([data-variant="ghost"])[data-effect="bubble"],
:root[data-glass-lens][data-glass-tint="frost"] .gb:not([data-variant="ghost"])[data-effect="glass"],
:root[data-glass-lens][data-glass-tint="frost"] .gb:not([data-variant="ghost"])[data-effect="bubble"] {
  --gb-backdrop: url(#glass-lens) blur(2px) saturate(1.7) brightness(1.08);
}
[data-glass-tint="frost"] .gb[data-variant="primary"][data-effect="bubble"] {
  --gb-inset: inset 0 1.5px 0 0 #fff, inset 0 9px 10px -6px rgb(255 255 255 / 0.9), inset 0 -10px 14px -7px rgb(60 72 98 / 0.3);
}

/* ---------- Ghost: text only, the surface arrives with the cursor ---------- */
.gb[data-variant="ghost"] {
  --gb-fill: rgb(255 255 255 / calc(0.65 * var(--g-glow)));
  --gb-backdrop: none;
  --gb-ring: rgb(var(--glass-shadow) / calc(0.08 * var(--g-glow)));
  --gb-drop: rgb(var(--glass-shadow) / calc(0.14 * var(--g-glow)));
  --gb-light: 0;
  box-shadow: 0 0 0 1px var(--gb-ring), 0 6px 14px -8px var(--gb-drop);
}

/* States */
.gb:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  --gb-drop: transparent;
}
.gb[aria-busy="true"] { cursor: progress; }

.gb-icon,
.gb-label { display: inline-flex; align-items: center; }
.gb svg { width: 1.15em; height: 1.15em; flex: none; }

.gb-spinner {
  width: 1em;
  height: 1em;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  border-right-color: transparent;
  animation: gb-spin 0.7s linear infinite;
}
@keyframes gb-spin { to { transform: rotate(360deg); } }

/* Where glass cannot blur, or should not, it becomes the flat finish so
   the label always stays readable. */
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .gb[data-variant="secondary"]:not([data-effect="flat"]) { --gb-fill: #fff; }
  .gb[data-variant="primary"]:not([data-effect="flat"]) { --gb-fill: var(--glass-tint); }
}
@media (prefers-reduced-transparency: reduce) {
  .gb[data-variant="secondary"]:not([data-effect="flat"]) { --gb-fill: #fff; }
  .gb[data-variant="primary"]:not([data-effect="flat"]) { --gb-fill: var(--glass-tint); }
}
@media (prefers-reduced-motion: reduce) {
  .gb-spinner { animation-duration: 1.6s; }
}

/* ---------- Mist over a dark picture ----------
   Add data-glass-on="dark" to a wrapper that sits on a dark photo or video.
   Glass and bubble buttons turn almost clear, with white text and a thin
   bright rim, so the picture stays the star. */
[data-glass-tint="frost"] [data-glass-on="dark"] .gb[data-effect="glass"],
[data-glass-tint="frost"] [data-glass-on="dark"] .gb[data-effect="bubble"],
[data-glass-tint="frost"][data-glass-on="dark"] .gb[data-effect="glass"],
[data-glass-tint="frost"][data-glass-on="dark"] .gb[data-effect="bubble"] {
  --gb-fg: #fff;
  --gb-fill: linear-gradient(180deg, rgb(255 255 255 / 0.2), rgb(255 255 255 / 0.06) 55%, rgb(255 255 255 / 0.12));
  --gb-inset: inset 0 1px 0 0 rgb(255 255 255 / 0.45), inset 0 -1px 0 0 rgb(255 255 255 / 0.12);
  --gb-ring: rgb(255 255 255 / 0.22);
  --gb-drop: rgb(0 0 0 / 0.35);
  --gb-rim-hi: rgb(255 255 255 / 0.8);
  --gb-rim-lo: rgb(255 255 255 / 0.08);
  --gb-light: 0.25;
}
[data-glass-tint="frost"] [data-glass-on="dark"] .gb[data-variant="primary"][data-effect="glass"],
[data-glass-tint="frost"] [data-glass-on="dark"] .gb[data-variant="primary"][data-effect="bubble"] {
  --gb-fill: linear-gradient(180deg, rgb(255 255 255 / 0.32), rgb(255 255 255 / 0.12) 55%, rgb(255 255 255 / 0.2));
}
[data-glass-tint="frost"] [data-glass-on="dark"] .gb[data-variant="primary"][data-effect="bubble"] {
  --gb-inset: inset 0 1.5px 0 0 rgb(255 255 255 / 0.7), inset 0 9px 10px -6px rgb(255 255 255 / 0.35), inset 0 -8px 12px -7px rgb(0 0 0 / 0.25);
}

/* Liquid glass refraction.
   Adds one hidden SVG filter (#glass-lens) to the page, once. Used as part of
   a backdrop-filter, it bends what sits behind a glass surface near its rim,
   the way thick glass does, while the middle stays clear.
   Only Chromium can use an SVG filter as a backdrop-filter, so the hook marks
   <html data-glass-lens> there and the CSS turns refraction on only then.
   Every other browser keeps the plain frosted glass. */
import { useEffect } from "react";

function lensMap() {
  const n = 128;
  const c = document.createElement("canvas");
  c.width = c.height = n;
  const ctx = c.getContext("2d");
  if (!ctx) return "";
  const img = ctx.createImageData(n, n);
  const ramp = (a, b, t) => {
    const x = Math.min(1, Math.max(0, (t - a) / (b - a)));
    return x * x * (3 - 2 * x);
  };
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      const u = (i / (n - 1)) * 2 - 1;
      const v = (j / (n - 1)) * 2 - 1;
      // Flat in the middle, bending hard in a band along the edge
      const kx = Math.sign(u) * ramp(0.7, 1, Math.abs(u));
      const ky = Math.sign(v) * ramp(0.3, 1, Math.abs(v));
      const o = (j * n + i) * 4;
      img.data[o] = 128 + 127 * kx;
      img.data[o + 1] = 128 + 127 * ky;
      img.data[o + 2] = 128;
      img.data[o + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return c.toDataURL();
}

export function useGlassLens(on = true) {
  useEffect(() => {
    if (!on || typeof document === "undefined" || document.getElementById("glass-lens")) return;
    const chromium = !!(navigator.userAgentData && navigator.userAgentData.brands && navigator.userAgentData.brands.length);
    if (!chromium) return;
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("width", "0");
    svg.setAttribute("height", "0");
    svg.style.position = "absolute";
    // Sized in each element's own box, so one filter fits every button
    svg.innerHTML =
      '<filter id="glass-lens" x="0" y="0" width="1" height="1" filterUnits="objectBoundingBox" primitiveUnits="objectBoundingBox" color-interpolation-filters="sRGB">' +
      '<feImage href="' + lensMap() + '" x="0" y="0" width="1" height="1" preserveAspectRatio="none" result="map"/>' +
      '<feDisplacementMap in="SourceGraphic" in2="map" scale="-0.2" xChannelSelector="R" yChannelSelector="G"/>' +
      "</filter>";
    document.body.appendChild(svg);
    document.documentElement.setAttribute("data-glass-lens", "");
  }, [on]);
}
